import React, {Component} from 'react';
import { Card, Col, Image } from 'react-bootstrap';
import { DivCenterPR } from '../../_assets/js/StylesDiv';
import api from '../../_config/api/binance';
import './styles.css';

class Carteira extends Component {
    
    state = {
        criptos: [
            {
                id: "inter-milan-fan-token",
                "symbol": "inter",
                "name": "Inter Milan Fan Token",
                "image": "https://assets.coingecko.com/coins/images/18288/large/chz.png?1631266631",
                "current_price": 28.35,
                "market_cap": 85069207,
                "market_cap_rank": 901,
                "fully_diluted_valuation": null,
                "total_volume": 1646830,
                "high_24h": 29.8,
                "low_24h": 28.41,
                "price_change_24h": -1.083140358617,
                "price_change_percentage_24h": -3.68032,
                "market_cap_change_24h": -3201419.977652386,
                "market_cap_change_percentage_24h": -3.62682,
                "circulating_supply": 3000212,
                "total_supply": 20000000,
                "max_supply": null,
                "ath": 74.77,
                "ath_change_percentage": -62.01647,
                "ath_date": "2021-10-22T10:37:40.750Z",
                "atl": 12.33,
                "atl_change_percentage": 130.34862,
                "atl_date": "2021-09-14T09:54:01.913Z",
                "roi": null,
                "last_updated": "2022-03-21T02:39:22.990Z"
            }
        ]
    }
        async componentDidMount(){
            const criptos_api = await api.get('cripto');

            this.setState({
                criptos: criptos_api.data
            })
        }

    render () {
        return (
        <>
            <DivCenterPR className="ajust-card">
                {this.state.criptos.map( cripto =>
                
                    <Col className="alin-card">
                        <Image className="confg-img" src={cripto.image} />
                        <Card.Title className="confg-title">{cripto.name}</Card.Title>
                        <Card.Text className="confg-text">{cripto.symbol}</Card.Text>
                        <Card.Text className="confg-text">R${cripto.current_price}</Card.Text>
                        <Card.Text className="confg-text">R${cripto.low_24h}</Card.Text>
                        <Card.Text className="confg-text">Maior Preço em 24H R${cripto.high_24h}</Card.Text>
                    </Col>
                )}
            </DivCenterPR>
        </>
        )
    }
}

export default Carteira;
